def _fbits(value: float) -> int:
    return struct.unpack("<I", struct.pack("<f", value))[0]


def build_entry(case, i: int) -> bytes:
    quat, old, current, new = case
    rng = random.Random(0x454E_5452 ^ i)
    entry = bytearray(rng.getrandbits(8) for _ in range(ENTRY_LEN))
    for lane, value in enumerate(quat):
        struct.pack_into("<I", entry, lane * 4, _fbits(value))
    for lane, value in enumerate(current):
        struct.pack_into("<I", entry, 0x10 + lane * 4, _fbits(value))
    struct.pack_into("<i", entry, 0x24, -1)
    return bytes(entry)


def build_record(i: int) -> bytes:
    rng = random.Random(0x5245_434F ^ i)
    record = bytearray(rng.getrandbits(8) for _ in range(RECORD_LEN))
    record[0x190] = 0
    return bytes(record)


def make_args(i: int) -> List[ArgSpec]:
    case = CASES[i % len(CASES)]
    quat, old, _, new = case
    block = b"".join(struct.pack("<I", _fbits(v)) for v in new)
    block += b"".join(struct.pack("<I", _fbits(v)) for v in old)
    return [
        ArgSpec(kind="ptr", mem=build_entry(case, i), arena_offset=ENTRY_OFF),
        ArgSpec(kind="ptr", mem=build_record(i), arena_offset=RECORD_OFF),
        ArgSpec(kind="ptr", mem=block, arena_offset=BLOCK_OFF),
    ]
